function validate(input) {
  const [{ Product = [], Sales = [] }] = input;
  const products = new Set(), sold = new Set();
  for (const [id, name] of Product) {
    if (id === null || name === null) return 'Product rows may not contain null.';
    if (products.has(id)) return `product_id ${id} appears twice in Product.`;
    products.add(id);
  }
  for (const row of Sales) {
    if (row.some((v) => v === null)) return 'Sales rows may not contain null.';
    const [id, start, end, daily] = row;
    if (sold.has(id)) return `product_id ${id} appears twice in Sales.`;
    if (!products.has(id)) return `Sales names unknown product ${id}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(start) || !/^\d{4}-\d{2}-\d{2}$/.test(end)) return 'Dates must look like 2019-01-31.';
    if (start > end) return `The period of product ${id} ends before it starts.`;
    if (start < '2018-01-01' || end > '2020-12-31') return 'Sales dates must lie in 2018 to 2020.';
    if (daily <= 0) return 'average_daily_sales must be positive.';
    sold.add(id);
  }
  return null;
}

