function generate(rand, size) {
  const names = ['LC Phone', 'LC T-Shirt', 'LC Keychain', 'LC Mug', 'LC Hoodie', 'LC Sticker'];
  const small = size === 'small';
  const day = (n) => new Date(Date.UTC(2018, 0, 1) + n * 86400000).toISOString().slice(0, 10);
  const last = 1095; // 2020-12-31
  const count = small ? Math.floor(rand() * 6) : 1200;
  const ids = Array.from({ length: count }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Product = ids.map((id) => [id, names[Math.floor(rand() * names.length)]]);
  const Sales = [];
  for (const [id] of Product) {
    if (rand() < 0.2) continue;
    // Starts and lengths often sit near year boundaries, and sometimes span all three years.
    const roll = rand();
    const start = roll < 0.3 ? [364, 365, 729, 730][Math.floor(rand() * 4)] : Math.floor(rand() * (last + 1));
    const length = roll > 0.85 ? last : Math.floor(rand() * (rand() < 0.5 ? 40 : 600));
    Sales.push([id, day(start), day(Math.min(last, start + length)), 1 + Math.floor(rand() * (small ? 20 : 500))]);
  }
  return [{ Product, Sales }];
}
